	@Test
	public void collectMaterializationValuesReusesPreviouslyReadDuplicateSlot() {
		long id = ValueIds.createId(ValueIds.T_DATETIME, 123L);
		Value expected = repository.getValueFactory().createLiteral("duplicate");
		StubSource source = new StubSource(Map.of(id, expected));
		NativeProjectedBindingSet row = new NativeProjectedBindingSet(source,
				new String[] { "first", "second" }, new int[] { 0, 1 }, new long[] { id, id });

		Value later = row.getValue("second");
		List<Value> collected = new ArrayList<>();
		row.collectMaterializationValues(collected::add);

		assertThat(collected).containsExactly(later, later);
		assertThat(source.lazyValueCalls).as("a pre-read duplicate ID must not be resolved again").isEqualTo(1);
	}

	private static void assertDuplicateProjectionResolvesOnce(long id) {
		Value expected = SimpleValueFactory.getInstance().createLiteral("duplicate");
		StubSource source = new StubSource(Map.of(id, expected));
		NativeProjectedBindingSet row = new NativeProjectedBindingSet(source,
				new String[] { "first", "second" }, new int[] { 0, 1 }, new long[] { id, id });
		List<Value> collected = new ArrayList<>();

		row.collectMaterializationValues(collected::add);

		assertThat(collected).containsExactly(expected, expected);
		assertThat(source.lazyValueCalls).as("duplicate ID %s must be resolved once", id).isEqualTo(1);
	}

	private void addRepeatedObjectRows(IRI predicate, String subjectPrefix, Value object, int count) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.begin();
			ValueFactory valueFactory = connection.getValueFactory();
			for (int i = 0; i < count; i++) {
				connection.add(valueFactory.createIRI(EX, subjectPrefix + i), predicate, object);
			}
			connection.commit();
		}
	}

	private void assertRawProjectionCounts(String queryText, int expectedRows, long expectedMaterializedValues) {
		NativeProjectedBindingSet.CREATED.set(0);
		NativeProjectedBindingSet.MATERIALIZED_VALUES.set(0);
		var query = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, queryText, null);
		try (var connection = repository.getSail().getConnection();
				var rows = connection.evaluate(query.getTupleExpr(), null, EmptyBindingSet.getInstance(), false)) {
			assertThat(rows.hasNext()).isTrue();
			assertThat(NativeProjectedBindingSet.MATERIALIZED_VALUES)
					.as("hasNext does not capture the current raw Sail row")
					.hasValue(0);
			int count = 0;
			while (rows.hasNext()) {
				rows.next();
				count++;
				long expectedAtThisRow = count == 1 ? 2 : count + 1L;
				assertThat(NativeProjectedBindingSet.MATERIALIZED_VALUES)
						.as("only values from accepted row %s are captured", count)
						.hasValue(expectedAtThisRow);
				if (rows.hasNext()) {
					assertThat(NativeProjectedBindingSet.MATERIALIZED_VALUES)
							.as("checking availability does not capture a later Sail row")
							.hasValue(expectedAtThisRow);
				}
			}
			assertThat(count).isEqualTo(expectedRows);
			assertThat(NativeProjectedBindingSet.MATERIALIZED_VALUES).hasValue(expectedMaterializedValues);
		}
	}

	private static void assertRepositoryValueReady(Value value) {
		if (value instanceof LmdbValue lmdbValue) {
			assertThat(lmdbValue.getValueStoreRevision()).isInstanceOf(ValueStoreRevision.Default.class);
			assertThat(lmdbValue.isInitialized()).isTrue();
		}
		if (value instanceof TripleTerm triple) {
			assertRepositoryValueReady(triple.getSubject());
			assertRepositoryValueReady(triple.getPredicate());
			assertRepositoryValueReady(triple.getObject());
		} else if (value instanceof Literal literal) {
			assertRepositoryValueReady(literal.getDatatype());
		}
	}

	private static Set<LmdbValue> nativeValues(Value value) {
		Set<LmdbValue> values = Collections.newSetFromMap(new IdentityHashMap<>());
		collectNativeValues(value, values);
		return values;
	}

	private static void collectNativeValues(Value value, Set<LmdbValue> values) {
		if (value instanceof LmdbValue lmdbValue) {
			values.add(lmdbValue);
		}
		if (value instanceof TripleTerm triple) {
			collectNativeValues(triple.getSubject(), values);
			collectNativeValues(triple.getPredicate(), values);
			collectNativeValues(triple.getObject(), values);
		} else if (value instanceof Literal literal) {
			collectNativeValues(literal.getDatatype(), values);
		}
	}

	@Test
	public void compiledStepReusesCanonicalDuplicateProjectionLayoutAcrossRows() {
		ValueFactory vf = repository.getValueFactory();
		Value firstX = vf.createLiteral("first x");
		Value y = vf.createLiteral("y");
		Value lastX = vf.createLiteral("last x");
		NativeLmdbQuerySource source = new StubSource(Map.of(11L, firstX, 22L, y, 33L, lastX));
		LinkedHashMap<String, Integer> slotNames = new LinkedHashMap<>();
		slotNames.put("firstX", 0);
		slotNames.put("y", 1);
		slotNames.put("lastX", 2);
		slotNames.put("missingX", 3);
		NativeSlotLayout slotLayout = new NativeSlotLayout(slotNames, null);
		slotLayout.freeze(List.copyOf(slotNames.keySet()));
		SlotPlan plan = new ValuesPlan(new ValuesRow[] { new ValuesRow(new int[] { 0 }, new long[] { 11L }) });
		NativeRowsStep step = new NativeRowsStep(source, plan, slotLayout, new int[] { 0, 1, 2, 3 },
				new String[] { "x", "y", "x", "x" }, false, new int[0], new boolean[0], 0L, -1L, false,
				null, null, null, Set.of(), null, null);
		AggContext values = new AggContext(source, false);

		NativeProjectedBindingSet first = (NativeProjectedBindingSet) step
				.project(new long[] { 11L, 22L, 33L, NativeLmdbQuerySource.UNKNOWN_ID }, values);
		NativeProjectedBindingSet second = (NativeProjectedBindingSet) step
				.project(new long[] { 11L, 22L, NativeLmdbQuerySource.UNKNOWN_ID,
						NativeLmdbQuerySource.UNKNOWN_ID }, values);

		assertThat(first.names)
				.as("immutable duplicate-name canonicalization belongs to the compiled projection")
				.isSameAs(second.names);
		assertThat(first.getValue("x")).isSameAs(lastX);
		assertThat(second.getValue("x")).isSameAs(firstX);
		assertThat(first.getValue("y")).isSameAs(y);
	}

